// Owner bootstrap: a single-use, short-lived setup token gates creation of the
// first (and only) panel administrator. Tokens are generated by the management
// CLI on the host — never by the public web flow.
//
// Worker-safe: no $app/* imports.
import { createHash, randomBytes } from 'node:crypto';
import { and, count, eq, gt, isNull } from 'drizzle-orm';
import { db } from '../db/index.js';
import { setupTokens } from '../db/schema.js';
import { user } from '../db/auth.schema.js';

export function hashSetupToken(token: string): string {
	return createHash('sha256').update(token).digest('hex');
}

export async function isOwnerInitialized(): Promise<boolean> {
	const rows = await db.select({ n: count() }).from(user);
	return (rows[0]?.n ?? 0) > 0;
}

/**
 * Create a new setup token. Returns the plaintext token (shown once) — only its
 * SHA-256 hash is stored.
 */
export async function createSetupToken(ttlMinutes = 30): Promise<string> {
	const token = `emp_setup_${randomBytes(24).toString('base64url')}`;
	await db.insert(setupTokens).values({
		tokenHash: hashSetupToken(token),
		label: 'owner-setup',
		expiresAt: new Date(Date.now() + ttlMinutes * 60_000)
	});
	return token;
}

/** Is this token currently usable? (does not consume) */
export async function validateSetupToken(token: string): Promise<boolean> {
	if (!token || (await isOwnerInitialized())) return false;
	const rows = await db
		.select({ id: setupTokens.id })
		.from(setupTokens)
		.where(
			and(
				eq(setupTokens.tokenHash, hashSetupToken(token)),
				isNull(setupTokens.consumedAt),
				gt(setupTokens.expiresAt, new Date())
			)
		)
		.limit(1);
	return rows.length > 0;
}

/**
 * Atomically consume a setup token. The UPDATE only matches an unconsumed,
 * unexpired token and no existing owner, so concurrent setup attempts cannot
 * both succeed. Returns true when this call consumed the token.
 */
export async function consumeSetupToken(token: string): Promise<boolean> {
	if (!token || (await isOwnerInitialized())) return false;
	const consumed = await db
		.update(setupTokens)
		.set({ consumedAt: new Date() })
		.where(
			and(
				eq(setupTokens.tokenHash, hashSetupToken(token)),
				isNull(setupTokens.consumedAt),
				gt(setupTokens.expiresAt, new Date())
			)
		)
		.returning({ id: setupTokens.id });
	return consumed.length > 0;
}
